  3	--- a/Sources/MurmurKit/TranscriptionEngine.swift
  4	+++ b/Sources/MurmurKit/TranscriptionEngine.swift
  5	@@ -44,6 +44,110 @@ public protocol LocalServerEngine: AnyObject {
  6	     func shutdown()
  7	 }
  8	 
  9	+/// A local model server whose memory macOS takes back while it idles on a Mac
 10	+/// short of memory: llama-server's mapped model file drops out of the page
 11	+/// cache, and the rest is compressed or swapped. The next request waits while
 12	+/// the weights come back: after 10 GB of other file reads, a 5 s dictation on
 13	+/// Qwen3-ASR 1.7B and the 3B cleanup model took 5.4 to 7.8 s (0.6 to 1.0 s
 14	+/// warm, M3 Pro, 36 GB). Started at key-down, the same page-in runs while the
 15	+/// user speaks: 0.9 to 1.1 s after a 3 s hold, 1.1 to 1.8 s after a 1 s hold.
 16	+public protocol Prewarmable: AnyObject {
 17	+    /// Sends one minimal request through the same server checks as a real
 18	+    /// one, so the model pages in while the user is still speaking. `prompt`
 19	+    /// is the one the next real request carries (vocabulary or cleanup
 20	+    /// system prompt), so the server caches its prefix. The task answers
 21	+    /// whether the server replied 200; the app ignores it.
 22	+    @discardableResult
 23	+    func prewarm(prompt: String?) -> Task<Bool, Never>
 24	+}
 25	+
 26	+public enum Prewarm {
 27	+    /// One second of 16 kHz silence: every layer of an audio model runs on it,
 28	+    /// and a resident model handles it in tens of milliseconds.
 29	+    public static let silence = WAVEncoder.encode(samples: [Int16](repeating: 0, count: 16_000),
 30	+                                                  sampleRate: 16_000)
 31	+
 32	+    /// Key-down: warms what the coming dictation calls, the batch STT engine
 33	+    /// with the dictation's vocabulary prompt and the local cleanup model.
 34	+    /// Streaming and cloud engines have nothing to warm. whisper-server is
 35	+    /// left out: it encodes a full 30 s window for any request and serves one
 36	+    /// request at a time, so on a warm server a prewarm delayed a 0.25 s
 37	+    /// dictation by 0.4 s.
 38	+    @discardableResult
 39	+    public static func forDictation(engine: TranscriptionProviding?, cleaner: Cleaner?,
 40	+                                    prompt: String?) -> [Task<Bool, Never>] {
 41	+        var tasks: [Task<Bool, Never>] = []
 42	+        if let local = engine as? Prewarmable { tasks.append(local.prewarm(prompt: prompt)) }
 43	+        if let cleanup = cleaner?.prewarm() { tasks.append(cleanup) }
 44	+        return tasks
 45	+    }
 46	+
 47	+    /// Reads the parts of the file missing from the page cache with plain
 48	+    /// reads, and returns once they are in. Blocks: call it off the main
 49	+    /// thread. Under memory pressure fcntl F_RDADVISE left 69-87% of a 1.6 GB
 50	+    /// model resident and lost more within seconds; plain reads took the same
 51	+    /// 0.4 s and kept all of it. False when the file cannot be opened, mapped
 52	+    /// or read.
 53	+    @discardableResult
 54	+    public static func readAhead(_ path: String) -> Bool {
 55	+        let fd = open(path, O_RDONLY)
 56	+        guard fd >= 0 else { return false }
 57	+        defer { close(fd) }
 58	+        var info = stat()
 59	+        guard fstat(fd, &info) == 0 else { return false }
 60	+        let size = Int(info.st_size)
 61	+        guard size > 0 else { return true }
 62	+        // mincore finds the resident pages: 10 ms for a warm 2 GB model,
 63	+        // against 165 ms to read it again.
 64	+        guard let map = mmap(nil, size, PROT_READ, MAP_SHARED, fd, 0), map != MAP_FAILED else { return false }
 65	+        defer { munmap(map, size) }
 66	+        let page = Int(getpagesize())
 67	+        var resident = [CChar](repeating: 0, count: (size + page - 1) / page)
 68	+        guard mincore(map, size, &resident) == 0 else { return false }
 69	+        let window = 4 << 20
 70	+        let buffer = UnsafeMutableRawPointer.allocate(byteCount: window, alignment: page)
 71	+        defer { buffer.deallocate() }
 72	+        var first = 0
 73	+        while first < resident.count {
 74	+            let last = min(first + window / page, resident.count)
 75	+            if resident[first..<last].contains(where: { $0 & 1 == 0 }) {
 76	+                let offset = first * page
 77	+                let length = min(window, size - offset)
 78	+                var done = 0
 79	+                while done < length {
 80	+                    let n = pread(fd, buffer, length - done, off_t(offset + done))
 81	+                    if n > 0 {
 82	+                        done += n
 83	+                    } else if n == 0 {
 84	+                        break // the file shrank
 85	+                    } else if errno != EINTR {
 86	+                        return false
 87	+                    }
 88	+                }
 89	+            }
 90	+            first = last
 91	+        }
 92	+        return true
 93	+    }
 94	+
 95	+    /// `readAhead` on a GCD thread, so the blocking read never holds one of
 96	+    /// Swift concurrency's few threads.
 97	+    static func readAheadInBackground(_ path: String) async {
 98	+        await withCheckedContinuation { (done: CheckedContinuation<Void, Never>) in
 99	+            DispatchQueue.global(qos: .userInitiated).async {
100	+                readAhead(path)
101	+                done.resume()
102	+            }
103	+        }
104	+    }
105	+
106	+    /// True when the request got a 200; false on any error.
107	+    static func send(_ request: URLRequest?, with session: URLSession) async -> Bool {
108	+        guard let request, let (_, response) = try? await session.data(for: request) else { return false }
109	+        return (response as? HTTPURLResponse)?.statusCode == 200
110	+    }
111	+}
