     1	import Foundation
     2	
     3	public enum QwenAsrError: Error, LocalizedError {
     4	    case binaryMissing(String)
     5	    case modelMissing(String)
     6	    case serverTimeout
     7	    case http(status: Int)
     8	    case badResponse
     9	
    10	    public var errorDescription: String? {
    11	        switch self {
    12	        case .binaryMissing: return "llama-server not installed (run scripts/install_qwen_asr.sh)"
    13	        case .modelMissing: return "Qwen3-ASR model missing (run scripts/install_qwen_asr.sh)"
    14	        case .serverTimeout: return "Local Qwen3-ASR server didn't start"
    15	        case .http(let status): return "Local Qwen3-ASR error \(status)"
    16	        case .badResponse: return "Unreadable response from the local Qwen3-ASR server"
    17	        }
    18	    }
    19	}
    20	
    21	/// Local transcription with Qwen3-ASR served by llama.cpp's `llama-server`
    22	/// and its audio projector (`--mmproj`), kept warm as a child process beside
    23	/// the cleanup server. The vocabulary prompt goes in as the system message,
    24	/// which Qwen3-ASR reads as spelling context, and the assistant turn is
    25	/// prefilled with the language tag so the model skips language detection.
    26	public final class QwenAsrEngine: TranscriptionEngine, LocalServerEngine, Prewarmable {
    27	    /// 60 s is about 750 audio tokens: with the vocabulary prompt and the
    28	    /// output it stays far inside `-c 4096`.
    29	    public static let maxChunkSeconds = 60.0
    30	
    31	    private let binaryPath: String
    32	    private let modelPath: String
    33	    private let mmprojPath: String
    34	    private let language: String
    35	    private let session: URLSession
    36	    private let server: ChildServer
    37	
    38	    public init(binaryPath: String, modelPath: String, mmprojPath: String, port: Int,
    39	                language: String = "en",
    40	                session: URLSession = LoopbackURLSession.make(resourceTimeout: 90)) {
    41	        let model = (modelPath as NSString).expandingTildeInPath
    42	        let mmproj = (mmprojPath as NSString).expandingTildeInPath
    43	        self.binaryPath = binaryPath
    44	        self.modelPath = model
    45	        self.mmprojPath = mmproj
    46	        self.language = language
    47	        self.session = session
    48	        self.server = ChildServer(name: "llama-server (Qwen3-ASR)", binaryPath: binaryPath,
    49	                                  port: port, session: session) { port in
    50	            Self.serverArguments(modelPath: model, mmprojPath: mmproj, port: port)
    51	        }
    52	    }
    53	
    54	    deinit { shutdown() }
    55	
    56	    public func transcribe(wav: Data, prompt: String?) async throws -> String {
    57	        try await ensureServerRunning()
    58	        return try await AudioChunker.transcribe(wav: wav, maxSeconds: Self.maxChunkSeconds) { piece in
    59	            try await ensureServerRunning() // a retry after a crash respawns the server
    60	            let request = try Self.makeTranscriptionRequest(wav: piece, prompt: prompt,
    61	                                                            language: language, port: server.port)
    62	            let (data, response) = try await session.data(for: request)
    63	            let status = (response as? HTTPURLResponse)?.statusCode ?? 0
    64	            guard status == 200 else { throw QwenAsrError.http(status: status) }
    65	            return try Self.parseResponse(data)
    66	        }
    67	    }
    68	
    69	    /// Spawns the server eagerly so the model is warm before the first
    70	    /// utterance. Safe to call repeatedly.
    71	    public func warmUp() {
    72	        Task.detached { [weak self] in try? await self?.ensureServerRunning() }
    73	    }
    74	
    75	    /// Reads the model file ahead (llama-server maps it; the projector is
    76	    /// loaded into memory) while the one-token request pages in the rest.
    77	    @discardableResult
    78	    public func prewarm(prompt: String?) -> Task<Bool, Never> {
    79	        Task.detached { [weak self] in
    80	            guard let self else { return false }
    81	            async let weights: Void = Prewarm.readAheadInBackground(self.modelPath)
    82	            var answered = false
    83	            if (try? await self.ensureServerRunning()) != nil {
    84	                answered = await Prewarm.send(try? Self.makePrewarmRequest(prompt: prompt, language: self.language,
    85	                                                                           port: self.server.port),
    86	                                              with: self.session)
    87	            }
    88	            await weights
    89	            return answered
    90	        }
    91	    }
    92	
    93	    public func shutdown() {
    94	        server.shutdown()
    95	    }
    96	
    97	    private func ensureServerRunning() async throws {
    98	        let ready = try await server.ensureRunning(polls: 120) {
    99	            guard LocalServer.isSafeToExecute(binaryPath) else {
   100	                throw QwenAsrError.binaryMissing(binaryPath)
   101	            }
   102	            for path in [modelPath, mmprojPath] where !FileManager.default.fileExists(atPath: path) {
   103	                throw QwenAsrError.modelMissing(path)
   104	            }
   105	        }
   106	        guard ready else { throw QwenAsrError.serverTimeout }
   107	    }
   108	
   109	    // MARK: pure request/argument builders (unit-tested)
   110	
   111	    /// Same minimal flag set as `LlamaCppChatEngine` plus the projector.
   112	    public static func serverArguments(modelPath: String, mmprojPath: String, port: Int) -> [String] {
   113	        ["-m", modelPath,
   114	         "--mmproj", mmprojPath,
   115	         "--host", "127.0.0.1",
   116	         "--port", String(port),
   117	         "-c", "4096",
   118	         "-ngl", "99",
   119	         "-t", String(max(4, ProcessInfo.processInfo.activeProcessorCount / 2))]
   120	    }
   121	
   122	    /// The silent clip with the prompt and prefill of a real request, one output token.
   123	    public static func makePrewarmRequest(prompt: String?, language: String, port: Int) throws -> URLRequest {
   124	        try makeTranscriptionRequest(wav: Prewarm.silence, prompt: prompt, language: language, port: port,
   125	                                     tokenLimit: 1)
   126	    }
   127	
   128	    /// `tokenLimit` nil: the output cap scales with the audio (`maxTokens(forWAVBytes:)`).
   129	    public static func makeTranscriptionRequest(wav: Data, prompt: String?, language: String,
   130	                                                port: Int, tokenLimit: Int? = nil) throws -> URLRequest {
   131	        var messages: [[String: Any]] = []
   132	        if let prompt, !prompt.isEmpty {
   133	            messages.append(["role": "system", "content": prompt])
   134	        }
   135	        messages.append(["role": "user", "content": [[
   136	            "type": "input_audio",
   137	            "input_audio": ["data": wav.base64EncodedString(), "format": "wav"],
   138	        ]]])
   139	        if let name = languageName(for: language) {
   140	            // llama-server continues a trailing assistant message.
   141	            messages.append(["role": "assistant", "content": "language \(name)<asr_text>"])
   142	        }
   143	        let body: [String: Any] = [
   144	            "messages": messages,
   145	            "temperature": 0,
   146	            "max_tokens": tokenLimit ?? maxTokens(forWAVBytes: wav.count),
   147	            "cache_prompt": true,
   148	        ]
   149	        var request = URLRequest(url: URL(string: "http://127.0.0.1:\(port)/v1/chat/completions")!)
   150	        request.httpMethod = "POST"
   151	        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
   152	        request.httpBody = try JSONSerialization.data(withJSONObject: body)
   153	        request.timeoutInterval = 60
   154	        return request
   155	    }
   156	
   157	    /// Output cap: 8 tokens per second of audio (fast speech runs about 6)
   158	    /// plus 64. A repetition loop stops at the cap.
   159	    public static func maxTokens(forWAVBytes bytes: Int) -> Int {
   160	        let seconds = Double(max(0, bytes - 44)) / 32_000
   161	        return Int(seconds * 8) + 64
   162	    }
   163	
   164	    /// Qwen3-ASR's name for an ISO 639 code; nil lets the model detect.
   165	    public static func languageName(for code: String) -> String? {
   166	        languageNames[code.lowercased()]
   167	    }
   168	
   169	    private static let languageNames: [String: String] = [
   170	        "en": "English", "zh": "Chinese", "yue": "Cantonese", "ar": "Arabic", "de": "German",
   171	        "fr": "French", "es": "Spanish", "pt": "Portuguese", "id": "Indonesian", "it": "Italian",
   172	        "ko": "Korean", "ru": "Russian", "th": "Thai", "vi": "Vietnamese", "ja": "Japanese",
   173	        "tr": "Turkish", "hi": "Hindi", "ms": "Malay", "nl": "Dutch", "sv": "Swedish",
   174	        "da": "Danish", "fi": "Finnish", "pl": "Polish", "cs": "Czech", "fil": "Filipino",
   175	        "fa": "Persian", "el": "Greek", "hu": "Hungarian", "mk": "Macedonian", "ro": "Romanian",
   176	    ]
   177	
   178	    /// The text after `<asr_text>` (the reply echoes the prefilled tag).
   179	    public static func parseResponse(_ data: Data) throws -> String {
   180	        struct Response: Decodable {
   181	            struct Choice: Decodable {
   182	                struct Msg: Decodable { let content: String? }
   183	                let message: Msg
   184	            }
   185	            let choices: [Choice]
   186	        }
   187	        guard let response = try? JSONDecoder().decode(Response.self, from: data),
   188	              let content = response.choices.first?.message.content else {
   189	            throw QwenAsrError.badResponse
   190	        }
   191	        var text = Substring(content)
   192	        if let tag = text.range(of: "<asr_text>") { text = text[tag.upperBound...] }
   193	        if let close = text.range(of: "</asr_text>") { text = text[..<close.lowerBound] }
   194	        return text.trimmingCharacters(in: .whitespacesAndNewlines)
   195	    }
   196	}

