 54	            try await ensureServerRunning() // a retry after a crash respawns the server
 55	            let request = Self.makeTranscriptionRequest(wav: piece, port: server.port)
 56	            let (data, response) = try await session.data(for: request)
 57	            let status = (response as? HTTPURLResponse)?.statusCode ?? 0
 58	            guard status == 200 else { throw ParakeetError.http(status: status) }
 59	            return try Self.parseResponse(data)
 60	        }
 61	    }
