47	/// A local model server whose memory macOS takes back while it idles on a Mac
48	/// short of memory: llama-server's mapped model file drops out of the page
49	/// cache, and the rest is compressed or swapped. The next request waits while
50	/// the weights come back: after 10 GB of other file reads, a 5 s dictation on
51	/// Qwen3-ASR 1.7B and the 3B cleanup model took 5.4 to 7.8 s (0.6 to 1.0 s
52	/// warm, M3 Pro, 36 GB). Started at key-down, the same page-in runs while the
53	/// user speaks: 0.9 to 1.1 s after a 3 s hold, 1.1 to 1.8 s after a 1 s hold.
54	public protocol Prewarmable: AnyObject {
55	    /// Sends one minimal request through the same server checks as a real
56	    /// one, so the model pages in while the user is still speaking. `prompt`
57	    /// is the one the next real request carries (vocabulary or cleanup
58	    /// system prompt), so the server caches its prefix. The task answers
59	    /// whether the server replied 200; the app ignores it.
60	    @discardableResult
61	    func prewarm(prompt: String?) -> Task<Bool, Never>
62	}
63	
64	public enum Prewarm {
65	    /// One second of 16 kHz silence: every layer of an audio model runs on it,
66	    /// and a resident model handles it in tens of milliseconds.
67	    public static let silence = WAVEncoder.encode(samples: [Int16](repeating: 0, count: 16_000),
68	                                                  sampleRate: 16_000)
69	
70	    /// Key-down: warms what the coming dictation calls, the batch STT engine
71	    /// with the dictation's vocabulary prompt and the local cleanup model.
72	    /// Streaming and cloud engines have nothing to warm. whisper-server is
73	    /// left out: it encodes a full 30 s window for any request and serves one
74	    /// request at a time, so on a warm server a prewarm delayed a 0.25 s
75	    /// dictation by 0.4 s.
76	    @discardableResult
77	    public static func forDictation(engine: TranscriptionProviding?, cleaner: Cleaner?,
78	                                    prompt: String?) -> [Task<Bool, Never>] {
79	        var tasks: [Task<Bool, Never>] = []
80	        if let local = engine as? Prewarmable { tasks.append(local.prewarm(prompt: prompt)) }
81	        if let cleanup = cleaner?.prewarm() { tasks.append(cleanup) }
82	        return tasks
83	    }
84	
85	    /// Reads the parts of the file missing from the page cache with plain
86	    /// reads, and returns once they are in. Blocks: call it off the main
87	    /// thread. Under memory pressure fcntl F_RDADVISE left 69-87% of a 1.6 GB
